package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
public class YouTubeFavoritesDataTest {
 @Test public void canonicalLinksKeepVideoAndPlaylistIdentityWithoutTracking(){String video="https://m.youtube.com/watch?v=aqz-KE-bpKQ";assertEquals(video,YouTubeFavoritesData.canonical("https://youtu.be/aqz-KE-bpKQ?si=tracking"));assertEquals(video,YouTubeFavoritesData.canonical("https://www.youtube.com/shorts/aqz-KE-bpKQ"));assertEquals(video,YouTubeFavoritesData.canonical("https://www.youtube.com/watch?v=aqz-KE-bpKQ&list=RDaqz-KE-bpKQ&si=x"));assertEquals("https://m.youtube.com/playlist?list=RDaqz-KE-bpKQ",YouTubeFavoritesData.playlist("https://www.youtube.com/watch?v=aqz-KE-bpKQ&list=RDaqz-KE-bpKQ"));for(String url:new String[]{"https://youtube.com.evil.test/watch?v=aqz-KE-bpKQ","javascript:alert(1)","https://user@youtube.com/watch?v=aqz-KE-bpKQ","http://youtube.com/watch?v=aqz-KE-bpKQ","https://youtube.com:443/watch?v=aqz-KE-bpKQ","https://m.youtube.com/results?search_query=abc","https://m.youtube.com/","https://m.youtube.com/watch?v=aqz-KE-bpKQ&v=aqz-KE-bpKQ"})assertEquals(url,"",YouTubeFavoritesData.canonical(url));}
 @Test public void deduplicationRenameRemovalAndRoundTripKeepOtherBookmarks(){YouTubeFavoritesData d=YouTubeFavoritesData.decode("");String a="https://youtu.be/aqz-KE-bpKQ",b="https://m.youtube.com/playlist?list=RDaqz-KE-bpKQ";assertTrue(d.save(a,"Chitãozinho & Xororó",10));assertTrue(d.save(b,"Playlist",20));assertTrue(d.save("https://www.youtube.com/watch?v=aqz-KE-bpKQ&si=123","Renomeado",30));assertEquals(2,d.items.size());assertEquals(10,d.find(a).added);assertEquals("Renomeado",d.find(a).title);YouTubeFavoritesData restored=YouTubeFavoritesData.decode(d.encode());assertTrue(restored.writable);assertEquals(2,restored.items.size());assertTrue(restored.remove(a));assertNotNull(restored.find(b));assertEquals(1,restored.items.size());}
 @Test public void limitEmptyNamesAndLargeInputAreHandled(){YouTubeFavoritesData d=YouTubeFavoritesData.decode("");for(int i=0;i<200;i++)assertTrue(d.save(String.format(java.util.Locale.ROOT,"https://m.youtube.com/watch?v=%011d",i),"Vídeo "+i,i));assertFalse(d.save("https://youtu.be/abcdefghijk","Excedente",1));assertFalse(d.save("https://youtu.be/aqz-KE-bpKQ","  ",1));assertTrue(d.save("https://m.youtube.com/watch?v=00000000001","Novo nome",999));assertEquals(200,d.items.size());assertEquals(160,YouTubeFavoritesData.title(new String(new char[200]).replace('\0','x')).length());assertEquals("a b",YouTubeFavoritesData.title(" a\nb "));}
 @Test public void corruptOrFutureDataIsReadOnlyAndCannotBeOverwritten(){for(String raw:new String[]{"{", "{\"version\":2,\"items\":[]}","{\"version\":1.5,\"items\":[]}","{\"version\":1,\"items\":[{\"url\":\"https://evil.test\",\"title\":\"X\",\"added\":1}]}"}){YouTubeFavoritesData d=YouTubeFavoritesData.decode(raw);assertFalse(d.writable);assertFalse(d.save("https://youtu.be/aqz-KE-bpKQ","X",1));assertFalse(d.remove("https://youtu.be/aqz-KE-bpKQ"));try{d.encode();fail("Read-only encode accepted");}catch(IllegalStateException expected){}}}
}
